import { icon } from '../../core/icon.baa5583345db.mjs';
import { normalizeLanguage } from '../../core/i18n.57f38a17789d.mjs';

const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const choice = ({ path, value, current, label, detail = '', iconName = 'spark' }) => `<button type="button" class="onboarding-choice" data-onboarding-path="${esc(path)}" data-onboarding-value="${esc(value)}" aria-pressed="${current === value}"><span class="onboarding-choice__icon">${icon(iconName,{size:17})}</span><span><strong>${esc(label)}</strong>${detail ? `<small>${esc(detail)}</small>` : ''}</span><span class="onboarding-choice__check">${current === value ? icon('check',{size:15}) : ''}</span></button>`;
const toggle = ({ path, checked, label, detail = '' }) => `<button type="button" class="onboarding-toggle" role="switch" aria-checked="${Boolean(checked)}" data-onboarding-toggle="${esc(path)}"><span><strong>${esc(label)}</strong>${detail ? `<small>${esc(detail)}</small>` : ''}</span><span class="onboarding-toggle__track"><i></i></span></button>`;

function screenOne(a, vi) {
  return `<div class="onboarding-screen"><header><span class="onboarding-step-icon">${icon('globe',{size:21})}</span><div><p>${vi?'BƯỚC 1 · BẮT ĐẦU':'STEP 1 · START'}</p><h1>${vi?'Thiết lập Nolane theo cách bạn làm việc':'Set up Nolane for the way you work'}</h1><span>${vi?'Chỉ những lựa chọn ảnh hưởng ngay đến trải nghiệm. Bạn có thể đổi lại bất kỳ lúc nào.':'Only choices that immediately improve the experience. Everything remains editable.'}</span></div></header><section><h2>${vi?'Ngôn ngữ giao diện':'Interface language'}</h2><div class="onboarding-grid onboarding-grid--3">${choice({path:'language',value:'system',current:a.language,label:vi?'Theo hệ thống':'System language',iconName:'monitor'})}${choice({path:'language',value:'vi',current:a.language,label:vi?'Tiếng Việt':'Vietnamese',iconName:'message'})}${choice({path:'language',value:'en',current:a.language,label:'English',iconName:'message'})}</div></section><section><h2>${vi?'Bạn chủ yếu dùng Nolane để làm gì?':'What will you mainly use Nolane for?'}</h2><div class="onboarding-grid">${[
    ['chat',vi?'Trò chuyện hằng ngày':'Everyday chat',vi?'Hỏi đáp, ý tưởng và công việc nhanh':'Questions, ideas and quick work','message'],
    ['writing',vi?'Viết và tóm tắt':'Writing and summaries',vi?'Tạo, sửa và cô đọng nội dung':'Create, revise and condense content','file'],
    ['learning',vi?'Học tập và nghiên cứu':'Learning and research',vi?'Giải thích sâu và tìm hiểu có cấu trúc':'Deep explanations and structured inquiry','search'],
    ['planning',vi?'Lập kế hoạch và dự án':'Planning and projects',vi?'Nhiệm vụ nhiều bước với tiến độ rõ ràng':'Multi-step missions with visible progress','activity'],
    ['software',vi?'Xây dựng phần mềm':'Building software',vi?'Mã nguồn, terminal, diff và kiểm thử':'Code, terminal, diffs and tests','code'],
    ['advanced',vi?'Vận hành agent chuyên sâu':'Advanced agent operations',vi?'Control Plane, policy và bằng chứng':'Control Plane, policy and evidence','settings']
  ].map(([value,label,detail,iconName])=>choice({path:'primaryUse',value,current:a.primaryUse,label,detail,iconName})).join('')}</div></section></div>`;
}

function screenTwo(a, vi) {
  return `<div class="onboarding-screen"><header><span class="onboarding-step-icon">${icon('message',{size:21})}</span><div><p>${vi?'BƯỚC 2 · CỘNG TÁC':'STEP 2 · COLLABORATION'}</p><h1>${vi?'Nolane nên trao đổi với bạn như thế nào?':'How should Nolane work with you?'}</h1><span>${vi?'Các lựa chọn này chỉ thay đổi cách trình bày và cộng tác, không thay đổi quyền agent.':'These choices affect presentation and collaboration, never agent authority.'}</span></div></header><section><h2>${vi?'Độ sâu câu trả lời':'Answer depth'}</h2><div class="onboarding-grid onboarding-grid--4">${[['concise',vi?'Ngắn gọn':'Concise'],['balanced',vi?'Cân bằng':'Balanced'],['detailed',vi?'Chi tiết':'Detailed'],['research',vi?'Nghiên cứu':'Research-grade']].map(([value,label])=>choice({path:'explanationDepth',value,current:a.explanationDepth,label,iconName:'activity'})).join('')}</div></section><section><h2>${vi?'Phong cách cộng tác':'Collaboration style'}</h2><div class="onboarding-grid onboarding-grid--4">${[['direct',vi?'Trực tiếp':'Direct'],['collaborative',vi?'Cộng tác':'Collaborative'],['teacher',vi?'Giảng giải':'Teacher'],['reviewer',vi?'Phản biện':'Reviewer']].map(([value,label])=>choice({path:'responseStyle',value,current:a.responseStyle,label,iconName:'spark'})).join('')}</div></section><section>${toggle({path:'askBeforeAmbiguousChanges',checked:a.askBeforeAmbiguousChanges,label:vi?'Hỏi trước khi thay đổi còn mơ hồ':'Ask before ambiguous changes',detail:vi?'Nolane tiếp tục tự động trong phạm vi đã được phê duyệt, nhưng dừng lại khi ý định chưa rõ.':'Nolane may continue inside approved scope, but pauses when intent is unclear.'})}</section></div>`;
}

function screenThree(a, vi) {
  return `<div class="onboarding-screen"><header><span class="onboarding-step-icon">${icon('layout',{size:21})}</span><div><p>${vi?'BƯỚC 3 · KHÔNG GIAN':'STEP 3 · WORKSPACE'}</p><h1>${vi?'Chọn điểm bắt đầu':'Choose your starting experience'}</h1><span>${vi?'Bạn luôn có thể chuyển trực tiếp giữa bốn tầng mà không làm dừng nhiệm vụ.':'You can always switch directly between all four levels without stopping work.'}</span></div></header><section><h2>${vi?'Tầng giao diện':'Experience level'}</h2><div class="onboarding-grid onboarding-grid--4">${[
    ['everyday',vi?'Hằng ngày':'Everyday',vi?'Trò chuyện và AI đơn giản':'Chat and simple AI'],
    ['workspace','Workspace',vi?'Nhiệm vụ và phê duyệt':'Missions and approvals'],
    ['studio','Studio',vi?'Tệp, terminal và diff':'Files, terminal and diffs'],
    ['expert',vi?'Chuyên sâu':'Expert',vi?'Toàn bộ Control Plane':'Full Control Plane']
  ].map(([value,label,detail])=>choice({path:'experience',value,current:a.experience,label,detail,iconName:value==='studio'?'code':value==='expert'?'settings':'layout'})).join('')}</div></section><section class="onboarding-appearance"><div><h2>${vi?'Giao diện':'Appearance'}</h2><label>${vi?'Chủ đề':'Theme'}<select data-onboarding-select="theme"><option value="system"${a.theme==='system'?' selected':''}>${vi?'Theo hệ thống':'System'}</option><option value="nocturne"${a.theme==='nocturne'?' selected':''}>Nocturne</option><option value="obsidian"${a.theme==='obsidian'?' selected':''}>Obsidian</option><option value="graphite"${a.theme==='graphite'?' selected':''}>Graphite</option><option value="aurora"${a.theme==='aurora'?' selected':''}>Aurora</option><option value="snow"${a.theme==='snow'?' selected':''}>Snow</option><option value="paper"${a.theme==='paper'?' selected':''}>Paper</option></select></label></div><div><h2>&nbsp;</h2><label>${vi?'Màu nhấn':'Accent'}<select data-onboarding-select="accent">${['violet','blue','cyan','rose','amber','emerald'].map(value=>`<option value="${value}"${a.accent===value?' selected':''}>${value}</option>`).join('')}</select></label></div><div><h2>&nbsp;</h2><label>${vi?'Mật độ':'Density'}<select data-onboarding-select="density"><option value="comfortable"${a.density==='comfortable'?' selected':''}>${vi?'Thoải mái':'Comfortable'}</option><option value="compact"${a.density==='compact'?' selected':''}>${vi?'Gọn':'Compact'}</option></select></label></div><div><h2>&nbsp;</h2><label>${vi?'Chuyển động':'Motion'}<select data-onboarding-select="motion"><option value="system"${a.motion==='system'?' selected':''}>${vi?'Theo hệ thống':'System'}</option><option value="full"${a.motion==='full'?' selected':''}>${vi?'Đầy đủ':'Full'}</option><option value="reduced"${a.motion==='reduced'?' selected':''}>${vi?'Giảm':'Reduced'}</option></select></label></div></section></div>`;
}

function screenFour(a, vi) {
  return `<div class="onboarding-screen"><header><span class="onboarding-step-icon">${icon('shield',{size:21})}</span><div><p>${vi?'BƯỚC 4 · DỮ LIỆU':'STEP 4 · DATA'}</p><h1>${vi?'Bộ nhớ, thông báo và quyền riêng tư':'Memory, notifications and privacy'}</h1><span>${vi?'Credential luôn ở OS vault. Onboarding không tự cấp thêm quyền cho agent.':'Credentials remain in the OS vault. Onboarding never grants extra agent authority.'}</span></div></header><section><h2>${vi?'Bộ nhớ qua phiên':'Cross-session memory'}</h2><div class="onboarding-grid onboarding-grid--3">${choice({path:'memoryMode',value:'off',current:a.memoryMode,label:vi?'Không ghi nhớ':'Do not remember',detail:vi?'Chỉ dùng ngữ cảnh phiên hiện tại':'Current session context only',iconName:'close'})}${choice({path:'memoryMode',value:'project',current:a.memoryMode,label:vi?'Ngữ cảnh dự án':'Project context',detail:vi?'Giữ thông tin phục vụ dự án':'Retain project-relevant context',iconName:'folder'})}${choice({path:'memoryMode',value:'approved',current:a.memoryMode,label:vi?'Preference đã duyệt':'Approved preferences',detail:vi?'Giữ preference và ngữ cảnh dự án':'Retain approved preferences and project context',iconName:'check'})}</div></section><section><h2>${vi?'Thông báo':'Notifications'}</h2><div class="onboarding-toggle-list">${toggle({path:'notifications.taskCompletion',checked:a.notifications.taskCompletion,label:vi?'Nhiệm vụ hoàn tất':'Mission completed'})}${toggle({path:'notifications.approvals',checked:a.notifications.approvals,label:vi?'Cần phê duyệt':'Approval required'})}${toggle({path:'notifications.errors',checked:a.notifications.errors,label:vi?'Lỗi hoặc bị chặn':'Errors or blocked work'})}${toggle({path:'notifications.desktop',checked:a.notifications.desktop,label:vi?'Thông báo desktop':'Desktop notifications'})}</div></section><section>${toggle({path:'telemetry',checked:a.telemetry,label:vi?'Chia sẻ telemetry chẩn đoán tối thiểu':'Share minimal diagnostic telemetry',detail:vi?'Mặc định tắt. Không bao gồm credential hoặc nội dung riêng tư.':'Off by default. Never includes credentials or private content.'})}</section></div>`;
}

export function renderOnboardingView(state = {}) {
  const a = state.answers ?? {}; const vi = normalizeLanguage(a.language) === 'vi';
  if (state.status === 'loading') return `<section class="onboarding-shell"><div class="onboarding-loading">${icon('activity',{size:20})}<span>${vi?'Đang tải thiết lập…':'Loading setup…'}</span></div></section>`;
  if (state.completed || state.required === false) return `<section class="onboarding-shell"><div class="onboarding-complete">${icon('check',{size:28})}<h1>${vi?'Nolane đã sẵn sàng':'Nolane is ready'}</h1><p>${vi?'Thiết lập của bạn đã được lưu.':'Your preferences have been saved.'}</p><button type="button" class="primary" data-onboarding-action="continue">${vi?'Mở Nolane':'Open Nolane'}</button></div></section>`;
  const screens = [screenOne, screenTwo, screenThree, screenFour];
  return `<section class="onboarding-shell"><div class="onboarding-card"><div class="onboarding-progress" role="progressbar" aria-label="${vi?'Tiến độ thiết lập':'Setup progress'}" aria-valuemin="1" aria-valuemax="4" aria-valuenow="${state.step + 1}">${[0,1,2,3].map(step=>`<span aria-hidden="true" data-state="${step<state.step?'done':step===state.step?'current':'future'}"></span>`).join('')}</div>${screens[state.step]?.(a,vi)??screens[0](a,vi)}${state.error?`<div class="onboarding-error" role="alert">${esc(state.error)}</div>`:''}<footer class="onboarding-actions"><button type="button" data-onboarding-action="skip"${state.saving?' disabled':''}>${vi?'Bỏ qua lúc này':'Skip for now'}</button><div>${state.step===0?`<button type="button" data-onboarding-action="recommended"${state.saving?' disabled':''}>${vi?'Dùng mặc định đề xuất':'Use recommended defaults'}</button>`:`<button type="button" data-onboarding-action="back"${state.saving?' disabled':''}>${vi?'Quay lại':'Back'}</button>`}<button type="button" class="primary" data-onboarding-action="${state.step===3?'complete':'next'}"${state.saving?' disabled':''}>${state.saving?(vi?'Đang lưu…':'Saving…'):state.step===3?(vi?'Hoàn tất':'Finish'):(vi?'Tiếp tục':'Continue')}</button></div></footer></div></section>`;
}
